package dev.sectile.network.api.packet

import dev.sectile.network.api.NetworkChannel

/**
 * Protocol metadata describing a packet registered in [PacketRegistry].
 *
 * Mirrors the `PacketInfo` entry generated by Hytale's protocol: numeric id,
 * name, allowed direction, QUIC channel, maximum payload size, and Zstd compression flag.
 */
data class PacketDefinition(
    val id: Int,
    val name: String,
    val direction: PacketDirection,
    val channel: NetworkChannel,
    val maxSize: Int,
    val compressed: Boolean,
) {
    /** `true` if this packet can be sent by the client to the server. */
    val inbound: Boolean get() = direction.inbound

    /** `true` if this packet can be sent by the server to the client. */
    val outbound: Boolean get() = direction.outbound

    override fun toString(): String = "$name#$id"
}
